fields.InputDefinition:
{
  "goal": "Assume you are already logged in at http://localhost:4200. Open the application switcher dropdown next to the logo, open Data Explorer, then the Dashboards section. Create a new dashboard using the 'New' button (choose Dashboard) — it opens directly in edit mode with an editable name input at the top. Change the dashboard name to something distinctive like 'CU Test Rename', then click Save. After it returns to view mode, go back to the dashboard list and confirm the renamed dashboard appears with the new name. Success is the edited name persisting and showing in the list. Pages can take 10-30s to load in this resource-constrained environment — wait, don't navigate away.",
  "startUrl": "http://localhost:4200",
  "allowedDomains": [
    "localhost",
    "*.auth0.com"
  ],
  "auth": {
    "bindings": [
      {
        "domains": [
          "localhost",
          "*.auth0.com"
        ],
        "method": {
          "Type": "Basic",
          "Username": "{{authUsername}}",
          "Password": "{{authPassword}}",
          "Strategy": "FormLogin"
        }
      }
    ]
  }
}
